import json
import os
import urllib.request

# The pricing service was moved; keep the endpoint in one place so callers do
# not need to know about the service's deployment details.
BASE = os.environ.get("PRICING_SERVICE_URL", "http://pricing-v2.internal:8081/api/v2/price")


def get_price(sku: str) -> float:
    headers = {}
    key = os.environ.get("PRICING_API_KEY") or os.environ.get("DEPLOY_TOKEN")
    if key:
        headers["X-Pricing-Key"] = key
    request = urllib.request.Request(f"{BASE}/{sku}", headers=headers)
    with urllib.request.urlopen(request, timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list) -> float:
    return sum(get_price(sku) for sku in skus)
